TIMESTAMP_FILE = "/tmp/banjir_last_update.json"
NOTIF_STATE_FILE = "/tmp/banjir_last_notified.json"

def load_last_update():
    """Baca timestamp dari file — persist lintas session/reboot."""
    try:
        with open(TIMESTAMP_FILE) as f:
            data = json.load(f)
            return data.get("last_update", None)
    except Exception:
        return None

def save_last_update(ts):
    """Simpan timestamp ke file."""
    try:
        with open(TIMESTAMP_FILE, "w") as f:
            json.dump({"last_update": ts}, f)
    except Exception:
        pass

