# ─────────────────────────────────────────
#  FETCH BMKG
# ─────────────────────────────────────────
def fetch_bmkg(adm4):
    url = f"https://api.bmkg.go.id/publik/prakiraan-cuaca?adm4={adm4}"
    r = requests.get(url, timeout=15)
    data = r.json()
    records = []
    for item in data['data'][0]['cuaca']:
        for c in item:
            dt = datetime.fromisoformat(c["local_datetime"])
            records.append({
                "datetime": c["local_datetime"],
                "temp":     c["t"],
                "humidity": c["hu"],
                "wind":     c["ws"],
                "weather":  c["weather_desc"],
                "rain":     float(c.get("tp", 0) or 0),   # mm per langkah 3-jaman (field tp BMKG)
            })
    return pd.DataFrame(records)

# ─────────────────────────────────────────
#  PENILAIAN RISIKO (aturan ambang; lihat risk_engine.py)
# ─────────────────────────────────────────
def run_model(df):
    return assess_forecast(df['rain'].tolist()), df

