# ─────────────────────────────────────────
#  SESSION STATE
# ─────────────────────────────────────────
for k,v in [
    ("hasil",None),
    ("df_bmkg",None),
    ("kecamatan_sel","Sutojayan"),
    ("last_notification", load_state(NOTIF_STATE_FILE))
]:
    if k not in st.session_state:
        st.session_state[k] = v

# Sync last_update dari file saat pertama load / setelah reboot
if "last_update" not in st.session_state:
    st.session_state["last_update"] = load_last_update()

REFRESH_INTERVAL = 60 * 60  # 60 menit

def should_refresh():
    if st.session_state.last_update is None: return True
    return (time.time() - st.session_state.last_update) >= REFRESH_INTERVAL

def do_predict(kec):
    adm4 = KECAMATAN.get(kec, "35.05.12.1005")
    df   = fetch_bmkg(adm4)
    hasil, df = run_model(df)

    check_and_send_notification(hasil)
    ts = time.time()
    st.session_state.hasil       = hasil
    st.session_state.df_bmkg     = df
    st.session_state.last_update = ts
    save_last_update(ts)  # simpan persisten ke file

# ─────────────────────────────────────────
#  NOTIFICATION SYSTEM
# ─────────────────────────────────────────
def check_and_send_notification(hasil):
    """Kirim notifikasi hanya saat status NAIK. Status terakhir disimpan di file agar tahan restart dan antar-sesi."""
    kirim, status_baru = next_state(load_state(NOTIF_STATE_FILE), hasil.status)
    if kirim:
        judul, isi = build_message(hasil)
        if send_notification(judul, isi):
            save_state(NOTIF_STATE_FILE, status_baru)
            st.session_state.last_notification = status_baru
    else:
        save_state(NOTIF_STATE_FILE, status_baru)

