render_header()

# ── st_autorefresh: rerun halaman tiap 1 detik untuk countdown realtime ──
# max 99999 supaya tidak berhenti, interval=1000ms
st_autorefresh(interval=1000, limit=99999, key="countdown_refresh")

tab_beranda, tab_info, tab_replay, tab_tentang = st.tabs([
    "🏠  Beranda",
    "📊  Informasi & Statistik",
    "🕰️  Uji Ulang Historis",
    "ℹ️  Tentang Kami"
])

with tab_beranda:  page_beranda()
with tab_info:     page_informasi()
with tab_replay:   page_replay()
with tab_tentang:  page_tentang()

# ── Trigger prediksi otomatis tiap 60 menit berdasarkan server time ──
# Dibaca dari file (persisten), bukan session state
persistent_ts = load_last_update()
if persistent_ts is None or (time.time() - persistent_ts) >= REFRESH_INTERVAL:
    # Sync ke session state dulu supaya do_predict tidak double-run
    if st.session_state.last_update != persistent_ts:
        st.session_state.last_update = persistent_ts
    with st.spinner("Auto-refresh: mengambil data BMKG terbaru..."):
        try:
            do_predict("Sutojayan")
            st.rerun()
        except Exception:
            pass